insert into sector_profiles (settore, version, status, pack, changelog)
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cosa succede alla prima valutazione?', $qofxmsq$["come funziona la prima valutazione","cosa si fa alla prima visita","cosa succede alla prima visita","in cosa consiste la prima valutazione","come funziona la prima visita","cosa si fa nella prima visita","cosa succede alla prima valutazione"]$qofxmsq$::jsonb, 'In genere la prima valutazione comprende alcune domande sul problema e sulla sua storia, l''osservazione dei movimenti e dei test specifici sulla zona interessata. Al termine il fisioterapista le illustra il percorso che ritiene più adatto. I dettagli possono variare da studio a studio.', $qh0vc13${}$qh0vc13$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Quante sedute servono?', $qgv6vh4$["quante sedute servono","quante sedute mi servono","quante sedute devo fare","di quante sedute ho bisogno","quante sedute ci vogliono","quante sedute sono necessarie"]$qgv6vh4$::jsonb, 'Il numero di sedute dipende dalla valutazione: varia in base al problema, a da quanto tempo c''è e alla persona, quindi non si può stabilire prima di averla valutata. È il fisioterapista a indicarlo dopo la prima valutazione.', $q7b69xq${}$q7b69xq$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Quanto dura una seduta?', $qn1667d$["quanto dura una seduta","quanto dura la seduta","quanto tempo dura la seduta","una seduta quanto dura","quanto tempo ci vuole per una seduta"]$qn1667d$::jsonb, 'La durata della seduta dipende dal tipo di trattamento e da come è organizzato lo studio: per il tempo esatto è meglio verificare direttamente con lo studio.', $q9kivke${}$q9kivke$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Ogni quanto si fanno le sedute?', $q6ks1v3$["ogni quanto si fanno le sedute","quante volte a settimana","quante sedute a settimana","con che frequenza si fanno le sedute","ogni quanto devo venire","ogni quanto vanno fatte le sedute"]$q6ks1v3$::jsonb, 'La frequenza delle sedute viene stabilita dal fisioterapista dopo la valutazione, in base al problema e al tipo di trattamento.', $qqnzpey${}$qqnzpey$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Quanto dura il percorso di fisioterapia?', $qb2c71b$["quanto dura il percorso di fisioterapia","quanto dura il ciclo di sedute","quanto dura il ciclo","quanto dura la terapia","quanto dura la riabilitazione","quanto tempo serve per recuperare","quanto dura la riabilitazione dopo l intervento"]$qb2c71b$::jsonb, 'La durata del percorso varia molto da persona a persona e dipende dal problema e dalla situazione di partenza: viene definita dal fisioterapista dopo la valutazione, non è possibile indicarla in anticipo.', $q40adp4${}$q40adp4$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cos''è un ciclo di sedute?', $qyu5fcu$["cos e un ciclo di sedute","cosa significa ciclo di sedute","in cosa consiste il ciclo di sedute","cosa vuol dire ciclo di sedute","come funziona il ciclo di sedute"]$qyu5fcu$::jsonb, 'Un ciclo è un percorso composto da più sedute, definito dal fisioterapista dopo la valutazione. Numero e cadenza delle sedute dipendono dal singolo caso.', $qkceo2s${}$qkceo2s$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_documenti', 'Serve l''impegnativa o la prescrizione medica?', $q08clvw$["serve l impegnativa","serve la prescrizione","serve la prescrizione medica","serve la ricetta del medico","ci vuole l impegnativa","serve l impegnativa del medico","posso venire senza impegnativa","posso venire senza prescrizione","si puo venire senza impegnativa","serve la richiesta del medico","ci vuole la prescrizione","serve il certificato medico"]$q08clvw$::jsonb, 'Dipende dallo studio e dal tipo di percorso (per esempio privato oppure in convenzione): in alcuni casi la prescrizione medica è richiesta, in altri no. È un aspetto da verificare con lo studio al momento della prenotazione.', $qo8j28y${}$qo8j28y$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_documenti', 'Cosa devo portare alla prima valutazione?', $q74f959$["cosa devo portare alla prima visita","cosa devo portare alla visita","cosa devo portare alla prima valutazione","che documenti servono per la prima visita","devo portare qualcosa alla prima visita","cosa serve portare","cosa devo portare","che documenti servono"]$q74f959$::jsonb, 'Alla prima valutazione è utile portare un documento di identità, la tessera sanitaria, gli eventuali referti ed esami già fatti (per esempio risonanza, radiografie, ecografie), la prescrizione se ne ha una e l''indicazione di eventuali interventi o terapie in corso. Per indicazioni precise verifichi con lo studio.', $qcs0cd1${}$qcs0cd1$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_documenti', 'Devo portare la risonanza o gli esami?', $qkrvuef$["devo portare la risonanza","devo portare le radiografie","devo portare gli esami","devo portare i referti","servono gli esami","serve la risonanza","serve la risonanza prima della visita","serve il referto","devo fare la risonanza prima"]$qkrvuef$::jsonb, 'Se ha già referti o esami (per esempio risonanza, radiografie, ecografie) è utile portarli: il fisioterapista li valuta insieme alla visita. Non sempre servono esami prima di venire: se ne serviranno, sarà il professionista a dirlo.', $qzz6eua${}$qzz6eua$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Come mi devo vestire per la seduta?', $q8l6wtg$["come mi devo vestire","cosa devo mettere","abbigliamento per la seduta","posso venire in jeans","cosa indossare alla visita","come mi vesto per la visita"]$q8l6wtg$::jsonb, 'È consigliabile un abbigliamento comodo, che permetta di muoversi e di scoprire facilmente la zona da valutare (per esempio una maglietta comoda e pantaloncini).', $qjios71${}$qjios71$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Che differenza c''è tra fisioterapista, fisiatra e osteopata?', $q1eojmq$["che differenza c e tra fisioterapista e osteopata","differenza tra fisioterapista e fisiatra","differenza fisioterapista osteopata","chi e il fisiatra","fisioterapista o osteopata","fisioterapista o fisiatra"]$q1eojmq$::jsonb, 'Il fisiatra è un medico specializzato in riabilitazione; il fisioterapista è il professionista sanitario che valuta il movimento e svolge i trattamenti riabilitativi; l''osteopata ha un approccio manuale con un proprio percorso formativo. Per capire a chi rivolgersi nel suo caso, la prima valutazione è il punto di partenza.', $qort17t${}$qort17t$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cos''è la tecarterapia?', $qy8lre1$["cos e la tecarterapia","come funziona la tecarterapia","cosa e la tecar","cos e la tecar","tecar cos e","cosa significa tecarterapia"]$qy8lre1$::jsonb, 'La tecarterapia è una terapia strumentale che utilizza energia a radiofrequenza applicata sulla zona da trattare. Se sia indicata nel suo caso lo decide il professionista; per sapere se lo studio la utilizza chieda direttamente allo studio.', $q1w2mrk${}$q1w2mrk$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cos''è la laserterapia?', $qvkefxm$["cos e la laserterapia","come funziona la laserterapia","cos e il laser","come funziona il laser","cosa e la terapia laser"]$qvkefxm$::jsonb, 'La laserterapia è una terapia strumentale che utilizza una luce laser applicata sulla zona da trattare. L''indicazione spetta al professionista; per sapere se lo studio la utilizza chieda direttamente allo studio.', $qw5yqfr${}$qw5yqfr$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cosa sono le onde d''urto?', $qzn8mcc$["cosa sono le onde d urto","come funzionano le onde d urto","cos e la terapia con onde d urto","in cosa consistono le onde d urto","cosa sono le onde urto"]$qzn8mcc$::jsonb, 'Le onde d''urto sono una terapia strumentale che usa onde acustiche applicate sulla zona da trattare. L''indicazione spetta al professionista; per sapere se lo studio la utilizza chieda direttamente allo studio.', $q4zhmlz${}$q4zhmlz$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cosa sono gli ultrasuoni?', $qev7523$["cosa sono gli ultrasuoni","come funzionano gli ultrasuoni","cos e l ultrasuonoterapia","cos e la terapia a ultrasuoni"]$qev7523$::jsonb, 'Gli ultrasuoni sono una terapia strumentale che utilizza onde sonore ad alta frequenza applicate sulla zona da trattare. L''indicazione spetta al professionista; per sapere se lo studio li utilizza chieda direttamente allo studio.', $qocwtl6${}$qocwtl6$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cos''è la massoterapia?', $qmroou5$["cos e la massoterapia","cosa e la massoterapia","in cosa consiste la massoterapia","cos e il massaggio terapeutico","differenza tra massaggio e massoterapia"]$qmroou5$::jsonb, 'La massoterapia è un trattamento manuale con tecniche di massaggio a scopo terapeutico, svolto da personale qualificato. Se sia indicata nel suo caso lo valuta il professionista; per sapere se lo studio la offre chieda direttamente allo studio.', $qlu1kwf${}$qlu1kwf$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cos''è l''osteopatia?', $qiw3p9u$["cos e l osteopatia","cosa e l osteopatia","in cosa consiste l osteopatia","come funziona l osteopatia","cosa fa l osteopata"]$qiw3p9u$::jsonb, 'L''osteopatia è un approccio manuale che valuta e tratta il corpo nel suo insieme. Per sapere se lo studio offre questo servizio e con quale professionista, chieda direttamente allo studio.', $qiikuoj${}$qiikuoj$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cos''è la rieducazione posturale?', $q6b28xo$["cos e la rieducazione posturale","cosa e la rieducazione posturale","in cosa consiste la rieducazione posturale","come funziona la rieducazione posturale","cos e la ginnastica posturale"]$q6b28xo$::jsonb, 'La rieducazione posturale è un percorso di esercizi e di lavoro sulla postura guidato dal fisioterapista, impostato dopo una valutazione. Per sapere se lo studio la offre chieda direttamente allo studio.', $qzkqdy5${}$qzkqdy5$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cos''è la terapia manuale o la mobilizzazione?', $q3ooe3g$["cos e la terapia manuale","cos e la mobilizzazione","cosa significa mobilizzazione","in cosa consiste la terapia manuale","cosa sono le mobilizzazioni"]$q3ooe3g$::jsonb, 'La terapia manuale comprende tecniche eseguite con le mani dal fisioterapista, come la mobilizzazione delle articolazioni e dei tessuti, scelte dopo la valutazione.', $qkfkwpn${}$qkfkwpn$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cos''è la ginnastica riabilitativa?', $q3lglr2$["cos e la ginnastica riabilitativa","cosa e la ginnastica riabilitativa","in cosa consiste la ginnastica riabilitativa","cos e la riabilitazione attiva"]$q3lglr2$::jsonb, 'La ginnastica riabilitativa è un percorso di esercizi impostato dal fisioterapista sulla base della valutazione e seguito in seduta. Gli esercizi adatti a lei li stabilisce il professionista, non possono essere indicati in chat.', $qr5w49q${}$qr5w49q$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'La seduta fa male?', $qh4mko0$["fa male la seduta","fa male la fisioterapia","la seduta e dolorosa","il trattamento e doloroso","la tecarterapia fa male","fa male il massaggio","fa male il trattamento"]$qh4mko0$::jsonb, 'Dipende dal tipo di trattamento e dalla persona. Il fisioterapista adatta l''intensità e va avvisato di qualsiasi fastidio durante la seduta.', $qjje50a${}$qjje50a$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Quando si può iniziare la riabilitazione dopo un intervento?', $qumbqj8$["quando iniziare la riabilitazione","quando si inizia la fisioterapia dopo l intervento","dopo quanto tempo dall intervento posso iniziare","quando posso iniziare dopo l operazione","quando posso cominciare la riabilitazione","quando devo iniziare la fisioterapia dopo l operazione"]$qumbqj8$::jsonb, 'Il momento giusto dipende dal tipo di intervento e dalle indicazioni del chirurgo: è importante seguire quanto le ha detto. Può comunque contattare lo studio per organizzare la valutazione.', $q2pr6ca${}$q2pr6ca$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Serve una diagnosi prima di venire?', $qx7bf25$["serve una diagnosi prima di venire","devo avere una diagnosi per venire","devo avere la diagnosi del medico","senza diagnosi posso venire","posso venire senza sapere cos ho"]$qx7bf25$::jsonb, 'Non sempre serve avere già una diagnosi: la prima valutazione serve proprio a capire la situazione. Se ha già referti o indicazioni del medico, è utile portarli.', $q7dz6qu${}$q7dz6qu$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Posso fare fisioterapia in gravidanza?', $qib88on$["sono incinta posso fare fisioterapia","in gravidanza posso venire","sono in gravidanza posso fare la seduta","fisioterapia in gravidanza","sono incinta posso venire"]$qib88on$::jsonb, 'Se è in gravidanza lo comunichi allo studio al momento della prenotazione: il fisioterapista valuta cosa è adatto al suo caso.', $qx18rmf${}$qx18rmf$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Posso prenotare per un familiare?', $qe9myt5$["posso prenotare per mio padre","posso prenotare per mia madre","posso prenotare per un familiare","prenotare per un altra persona","prenoto per mio marito"]$qe9myt5$::jsonb, 'In genere sì: basta indicare il nome della persona che verrà vista. Per eventuali indicazioni particolari, per esempio per minori, chieda allo studio.', $qgogaoy${}$qgogaoy$::jsonb);
insert into sector_test_scenarios (settore, codice, categoria, scenario) values ('fisioterapista', 'FI01', 'BOOKING', $q2pat0z${"scenario":{"input":"Buongiorno, vorrei prenotare una prima valutazione","expected":{"intent":"prenota_valutazione","entities":{"tipo_visita":"prima_valutazione"},"action":"ask_missing_information","next_question":"zona_corpo","safety":"LOW"},"tenant":{"campi":["nome_paziente","zona_corpo","durata_problema"],"haCalendario":true,"info_generali":{"indirizzo":"via dei Tigli","prezzi_note":"prima valutazione 55 euro, seduta singola 45 euro","altre_informazioni":"parcheggio, ascensore"}}}}$q2pat0z$::jsonb) on conflict (settore, codice) do update set categoria = excluded.categoria, scenario = excluded.scenario;
